class Base {
    Base() { /* Base ctor runs FIRST (1) */ }
    Base(const Base&) { /* Base copy ctor runs FIRST (1) */ }
};

class Derived : public Base {
    Derived() { /* Derived ctor runs SECOND (2) */ }
    Derived(const Derived& d)
        : Base(d) { /* Derived copy ctor runs SECOND (2) */ }
};

// CRITICAL ORDER:
// Initialization: Base::Base() -> Derived::Derived()
// Copying:        Base::Base(d) -> Derived::Derived(d)
// Destruction:    Derived::~() -> Base::~() (Reverse order)
